:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #243b35;
  background: #f3ead8;
}

* { box-sizing: border-box; }

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 20px;
  display: grid;
  place-items: center;
  background-color: #f3ead8;
  background-image: radial-gradient(#d9c9aa 1px, transparent 1px);
  background-size: 18px 18px;
}

.card {
  width: min(100%, 560px);
  padding: clamp(24px, 6vw, 48px);
  background: #fffdf7;
  border: 3px solid #243b35;
  border-radius: 8px;
  box-shadow: 8px 8px 0 #243b35;
}

.header { text-align: center; }
.pixel-sun {
  width: 42px;
  height: 42px;
  margin: 0 auto 18px;
  background: #e6a84b;
  box-shadow: 12px 0 #e6a84b, -12px 0 #e6a84b, 0 12px #e6a84b, 0 -12px #e6a84b;
  image-rendering: pixelated;
}
.eyebrow, .result-label {
  color: #55756a;
  font-size: 0.875rem;
  font-weight: 800;
  letter-spacing: 0.12em;
}
.eyebrow { margin: 0 0 8px; }
h1 { margin: 0; font-size: clamp(2.5rem, 10vw, 3.5rem); line-height: 1.05; letter-spacing: -0.06em; }
.intro { margin: 14px 0 30px; color: #53655e; line-height: 1.5; }

.date-fields { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.date-field {
  display: grid;
  gap: 8px;
  padding: 16px;
  border: 2px solid #d9c9aa;
  border-radius: 6px;
  background: #fffaf0;
}
.field-number { color: #a47a38; font-size: 0.875rem; font-weight: 800; letter-spacing: 0.08em; }
.field-title { font-weight: 750; }
input {
  width: 100%;
  min-height: 44px;
  padding: 8px 6px;
  border: 2px solid #d9c9aa;
  border-radius: 4px;
  background: #fffdf7;
  color: #243b35;
  font: inherit;
}
input:hover { border-color: #55756a; }
input:focus-visible, button:focus-visible { outline: 3px solid #e6a84b; outline-offset: 3px; }

button {
  width: 100%;
  min-height: 54px;
  margin-top: 18px;
  padding: 12px 18px;
  border: 2px solid #243b35;
  border-radius: 5px;
  background: #55756a;
  color: #fffdf7;
  font: inherit;
  font-weight: 800;
  cursor: pointer;
  transition: background-color 120ms ease, transform 120ms ease, box-shadow 120ms ease;
}
button span { margin-left: 8px; font-size: 1.2em; }
button:hover { background: #3f6256; }
button:active { transform: translate(2px, 2px); box-shadow: inset 0 2px 3px #243b35; }

.results { margin-top: 30px; padding-top: 24px; border-top: 2px dashed #d9c9aa; }
h2 { margin: 0 0 14px; font-size: 1.125rem; }
.result-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.result-tile { min-height: 110px; padding: 16px; border-radius: 5px; background: #f3ead8; }
.weeks-tile { background: #e8eee8; }
.result-label { font-size: 0.75rem; }
.result-value { margin: 8px 0 0; color: #243b35; font-size: clamp(2rem, 8vw, 2.75rem); font-weight: 850; line-height: 1; }
.direction { min-height: 48px; margin: 14px 0 0; padding: 13px 14px; border-left: 4px solid #e6a84b; background: #fffaf0; line-height: 1.45; }
footer { margin-top: 24px; color: #718078; text-align: center; font-size: 0.875rem; }

@media (max-width: 440px) {
  body { padding: 20px 16px; }
  .date-fields { grid-template-columns: 1fr; }
  .date-field { grid-template-columns: 36px 1fr; align-items: center; }
  .date-field input { grid-column: 1 / -1; }
}

const form = document.getElementById('date-form');
const firstDate = document.getElementById('first-date');
const secondDate = document.getElementById('second-date');
const daysResult = document.getElementById('days-result');
const weeksResult = document.getElementById('weeks-result');
const directionResult = document.getElementById('direction-result');
const DAY_MS = 24 * 60 * 60 * 1000;

function toUtcDay(dateString) {
  const [year, month, day] = dateString.split('-').map(Number);
  return Date.UTC(year, month - 1, day);
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  if (!form.reportValidity()) return;

  const first = toUtcDay(firstDate.value);
  const second = toUtcDay(secondDate.value);
  const difference = Math.abs(second - first) / DAY_MS;

  daysResult.textContent = difference.toLocaleString();
  weeksResult.textContent = Math.floor(difference / 7).toLocaleString();
  directionResult.textContent = second < first
    ? 'The second date is before the first.'
    : second > first
      ? 'The second date is after the first.'
      : 'Both dates are the same day.';
});
